import { gsap } from 'gsap';
import { Group } from '@/primitives';

/**
 * @typedef {Object} NodeConfig
 * @property {string} meshUrl
 * @property {Array<{name:string,params?:Object,trigger?:string}>} cinematicPrimitives
 */

/**
 * @typedef {Object} NodeContext
 * @property {any} THREE
 * @property {any} glbLoader
 * @property {any} emit
 * @property {any} primitives
 */

/**
 * Creates a compact metric card node.
 *
 * @param {NodeConfig} config
 * @param {NodeContext} ctx
 * @returns {THREE.Object3D}
 */
export default function createNode(config, ctx) {
  const { Group } = ctx.THREE;
  const root = new Group();

  /** Store handles for cleanup */
  const primitiveHandles = [];
  const interactionState = {
    hoverTimeline: null,
  };
  let gltfGroup = null;

  /* ---------------------------------------------------------------------- */
  /* Cinematic primitives */
  const cinPrims = config.cinematicPrimitives ?? [];
  for (const prim of cinPrims) {
    const handler = ctx.primitives[prim.name];
    if (handler) {
      const result = handler(root, prim.params ?? {});
      if (result) primitiveHandles.push(result);
    }
  }

  /* ---------------------------------------------------------------------- */
  /* Load GLB mesh */
  if (config.meshUrl) {
    ctx.glbLoader.loadGLB(config.meshUrl).then((gltf) => {
      gltfGroup = gltf.scene || gltf;
      root.add(gltfGroup);
    });
  }

  /* ---------------------------------------------------------------------- */
  /* Interaction handlers (exposed via userData) */
  root.userData.handlers = {};

  // hover lift – rise‑in (subtle 0.15 units)
  root.userData.handlers.hover = () => {
    if (interactionState.hoverTimeline) interactionState.hoverTimeline.kill();
    interactionState.hoverTimeline = gsap.to(root.position, {
      y: (root.position.y || 0) + 0.15,
      duration: 0.7,
      ease: 'power3.out',
    });
  };

  // hover out – return to base
  root.userData.handlers.unhover = () => {
    if (interactionState.hoverTimeline) interactionState.hoverTimeline.kill();
    interactionState.hoverTimeline = gsap.to(root.position, {
      y: 0,
      duration: 0.7,
      ease: 'power3.out',
    });
  };

  // click – emit navigation event
  root.userData.handlers.click = () => {
    ctx.emit('hub-home.select', {});
  };

  /* ---------------------------------------------------------------------- */
  /* Cleanup */
  root.userData.cleanup = () => {
    // Kill interaction timelines
    if (interactionState.hoverTimeline) interactionState.hoverTimeline.kill();

    // Cleanup cinematic primitives
    for (const h of primitiveHandles) {
      if (h && typeof h.cleanup === 'function') h.cleanup();
    }

    // Dispose GLTF resources
    if (gltfGroup) {
      gltfGroup.traverse((obj) => {
        if (obj.isMesh) {
          if (obj.geometry) obj.geometry.dispose();
          if (obj.material) {
            if (Array.isArray(obj.material)) {
              obj.material.forEach((m) => m.dispose());
            } else {
              obj.material.dispose();
            }
          }
        }
      });
    }
  };

  return root;
}
